// Everything the bot says that isn't generated by the interviewer.
// Each inner array is sent as separate bubbles (iMessage) or joined into one message (ASI:One),
// so wording stays channel-neutral: "reply", not "text".

export const WELCOME = [
  "hey! 👋 I'm the agent that's going to help you find your people",
  "I'll ask a few quick things, then we'll just chat for ~10 min so I can represent you well",
  "first up: what's your full name?",
];

// Used instead of WELCOME + ACCOUNTS when we already have their name from the join page.
export const WELCOME_POOL = (pool: string) => [
  `hey! 👋 welcome to ${pool}. I'm the agent that's going to help you find your people`,
  ...WELCOME.slice(1),
];

export const POOL_OK = (pool: string) => [`got it, welcome to ${pool}!`, ...WELCOME.slice(1)];

export const WELCOME_GENERAL = [
  "got it, I'll put you in the general pool",
  "I'll ask a few quick things, then we'll just chat for ~10 min so I can represent you well",
  "first up: what's your full name?",
];

export const ASK_POOL = [
  "hey! 👋 I'm the agent that's going to help you find your people",
  "which group are you joining? paste the \"join …\" line from your invite link, or reply \"no code\" to join the general pool",
];

export const BAD_CODE =
  'hmm, I couldn\'t find that invite code, or that group isn\'t taking new people anymore. double-check the "join …" line on your invite page, or reply "no code" to join the general pool';

export const WELCOME_KNOWN = (first: string) => [
  `hey ${first}! 👋 I'm the agent that's going to help you find your people`,
  "I'll ask a few quick things, then we'll just chat for ~10 min so I can represent you well",
  ...ACCOUNTS(first).slice(1),
];

export const ACCOUNTS = (first: string) => [
  `nice to meet you, ${first}!`,
  "which accounts should we pull from to get a feel for what you're into? e.g. Instagram, Spotify, Letterboxd, Goodreads, Strava, Beli, LinkedIn",
  "send handles if you have them (like \"spotify: alex.music, letterboxd @alexfilms\"), or reply \"skip\". we'll use these later to add more context to your profile",
];

export const ACCOUNTS_ACK = (platforms: string[], scraping = false) =>
  !platforms.length
    ? "no worries, we can skip that"
    : scraping
      ? `got it: ${platforms.join(", ")}. I'll take a look at the public ones while you do the next bit`
      : `got it: ${platforms.join(", ")}. we'll use those later for extra context`;

export const PASTE_INTRO = [
  "next, a shortcut: copy the prompt below into whatever AI you use most (ChatGPT, Claude, etc.)",
  "it'll write up what it knows about you. paste its whole reply back here and you can review everything before it's saved",
];

export const PASTE_OUTRO = 'paste the reply here when it\'s ready, or reply "skip" if you\'d rather just chat';

export const PASTE_PARTIAL =
  'got part of it, but no profile JSON yet. long replies sometimes split, so send the rest, or reply "done" if that was everything';

export const PASTE_NO_JSON =
  "I couldn't find the JSON block at the end of that, so I'll cover those topics in our chat instead";

export const PASTE_OK = (n: number) =>
  n
    ? `perfect, got it 🙌 ${n} thing${n === 1 ? "" : "s"} I want to double-check or fill in, so let's chat`
    : "perfect, got it 🙌 just a few things I want to ask about";

export const PASTE_SKIPPED = "all good, we'll do it the fun way and just chat";

export const REVIEW_INTRO = "ok here's what I've got. tell me anything that's off, in your own words";

export const REVIEW_ASK = 'reply "looks good" if this is right, or tell me what to change';

export const DEALBREAKERS_ASK = (items: string[]) => [
  "last thing. these are the only things I'd treat as hard dealbreakers, meaning I'd never match you with someone who has them. they stay private too:",
  items.map((d, i) => `${i + 1}. ${d}`).join("\n"),
  'reply "confirm" to lock these in, or tell me what to add/remove',
];

export const NO_DEALBREAKERS_ASK = [
  "last thing: I didn't pick up any hard dealbreakers, meaning things that would rule someone out completely",
  'is there anything? reply "none" if not',
];

export const DONE = (pool?: string) => [
  pool ? `you're all set ✨ your profile is saved and you're in ${pool}` : "you're all set ✨ your profile is saved",
  "I'll message you here when I've found a group I think you'll actually enjoy",
];

export const ALREADY_DONE = 'you\'re already onboarded! reply "restart" if you want to redo your profile';

export const TEXT_ONLY = "I can only read text for now, mind typing that out?";

export const ERROR = "sorry, something glitched on my end. can you send that again?";

// Verbatim from the project brief. Sent as its own bubble so it's easy to long-press → Copy.
export const AI_PROMPT = `I'm joining a service where an AI agent represents me to meet people and form small friend groups. Using everything you know about me from our conversations (including memory, if you have it), write a profile of me that would help that agent represent me well.

Rules:
- Only use what you've actually seen from me. Tag each point [observed] if it comes from something I said or did, or [inferred] if it's your interpretation. Include a brief example where you can.
- Prefer specific details over generic traits. "Will happily spend an hour comparing ramen broths" beats "likes food."
- Leave out health, finances, named people in my life, and anything sensitive. I'll review this before sharing it.
- If you don't know something, write "unknown." Don't guess to fill gaps.

Cover:
1. Interests: what I actually do (not just like), what I've gone deep on, current obsessions.
2. How I think: how I approach problems and decisions, what makes me curious, what I tend to push back on.
3. How I communicate: tone, humor style (with an example), how I sound when excited vs. annoyed, whether I'm brief or detailed.
4. Social energy: how I like to spend time, pace, planned vs. spontaneous, one-on-one vs. groups.
5. Values: what I care about, what frustrates me in other people.
6. Small details and quirks: habits, specific tastes (food, music, places), recurring jokes, things that make me distinctly me.
7. Group role: am I more of a connector, planner, easygoing one, storyteller, or something else? Explain your reasoning.
8. Possible dealbreakers: things I've reacted strongly against.
9. Things that might surprise someone: traits I might underrate in myself, or that don't show up right away. Be honest but kind.

End with the same information as a JSON object in this shape:
{"interests": [], "thinking_style": "", "communication": {"tone": "", "humor": "", "example": ""}, "social_energy": "", "values": [], "frustrations": [], "quirks": [], "group_role": "", "possible_dealbreakers": [], "surprising_traits": [], "unknowns": []}`;
